& git.exe -C "$a" commit -m "Opprett kursside"
if ($LASTEXITCODE -ne 0) { throw 'STOPP: Git-kommandoen feilet. Les meldingen og undersoek tilstanden.' }
& git.exe -C "$a" remote add origin "$remote"
if ($LASTEXITCODE -ne 0) { throw 'STOPP: Git-kommandoen feilet. Les meldingen og undersoek tilstanden.' }
& git.exe -C "$a" remote -v
if ($LASTEXITCODE -ne 0) { throw 'STOPP: Git-kommandoen feilet. Les meldingen og undersoek tilstanden.' }
& git.exe -C "$a" status -sb
if ($LASTEXITCODE -ne 0) { throw 'STOPP: Git-kommandoen feilet. Les meldingen og undersoek tilstanden.' }
}

