if ($LASTEXITCODE -ne 0 -or -not [string]::IsNullOrEmpty(($pending -join ''))) { throw 'STOPP: Arbeidskopien har endringer. Undersoek foerst.' }
& git.exe --git-dir="$remote" show-ref --verify --quiet refs/heads/main
